Paleontologist: No, the ability to perch in trees is not good evidence that Archeopteryx was a tree-dwelling bird. 
Chickens also spend time perched in trees, yet chickens are primarily ground-dwelling.$batch05$ AND q.prompt=$batch05$In responding to the ornithologist's hypothesis that Archeopteryx was tree-dwelling, the paleontologist$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT102-S3-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT102-S3-Q8$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S3-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT102-S3-Q8$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Paleontologist) Being able to perch in trees is not good evidence that Archeopteryx lived in trees.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Chickens perch in trees too, yet they mostly live on the ground.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The ornithologist's chain is "perches in trees, so lives in trees." The paleontologist does not dispute that Archeopteryx could perch. Instead, they produce another animal that perches and does not live in trees. One clear case breaks the link. That is a parallel case used to show a weak step.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A parallel case that shows the evidence does not support the conclusion.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT102-S3-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The paleontologist never questions the ornithologist's credentials.$batch05$), ($batch05$B$batch05$, $batch05$The second-speaker rule applies here. The paleontologist accepts the claw evidence ("the ability to perch in trees") and attacks the step from it to the conclusion.$batch05$), ($batch05$C$batch05$, $batch05$Chickens are the parallel case. Same trait, perching, but a different lifestyle. That shows the weakness: perching does not establish tree-dwelling.$batch05$), ($batch05$D$batch05$, $batch05$The hypothesis does not contradict its own evidence. The paleontologist says the evidence is too weak, not that it conflicts.$batch05$), ($batch05$E$batch05$, $batch05$The paleontologist is attacking the argument, not adding to it.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT102-S3-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
